const concepts=[["HTML", "HyperText Markup Language", "Lenguaje de marcado de hipertexto", "Describe la estructura y el significado del contenido de una página. Es un lenguaje de marcado; no se clasifica como lenguaje de programación.", "HTML organiza el título, los párrafos y los enlaces de Café Aurora.", "<h1>Café Aurora</h1>", [["HyperText", "Hipertexto: texto conectado mediante enlaces."], ["Markup", "Marcado: indica la estructura y el significado del contenido."], ["Language", "Lenguaje: conjunto de reglas para expresarlo."]]], ["CSS", "Cascading Style Sheets", "Hojas de estilo en cascada", "Define la presentación: colores, tipografía, tamaños y distribución. La cascada determina cómo se combinan y priorizan las declaraciones de estilo.", "CSS puede organizar las tarjetas del panel en columnas.", ".kpi-grid { display: grid; gap: 16px; }", [["Cascading", "En cascada: las reglas se combinan siguiendo criterios de prioridad."], ["Style", "Estilo: presentación visual del contenido."], ["Sheets", "Hojas: conjuntos de reglas de estilo."]]], ["JavaScript · JS", "JavaScript", "JavaScript (el nombre se conserva en español)", "Lenguaje de programación que permite añadir lógica y comportamiento. JS es la abreviatura de JavaScript, no una sigla de varias palabras. Java y JavaScript son lenguajes diferentes.", "Permite responder al clic de un botón o actualizar un texto.", "document.querySelector(\"button\").addEventListener(\"click\", () => {\n  alert(\"Hola\");\n});", []], ["Página web", "Web page", "Página web", "Documento que el navegador presenta y que suele tener su propia dirección dentro de un sitio.", "La página de contacto es una página dentro del sitio de una cafetería.", null, []], ["Sitio web", "Website", "Sitio web", "Conjunto relacionado de páginas y recursos, normalmente bajo un mismo dominio. También puede contener una sola página.", "Inicio, menú y contacto pueden formar el sitio de Café Aurora.", null, []], ["Diseño web", "Web design", "Diseño web", "Planificación de la estructura, apariencia y experiencia de uso de un sitio: organización, tipografía, color, navegación y adaptación a pantallas.", "En Figma puedes planificar el panel antes de escribir el código.", null, []], ["Desarrollo web", "Web development", "Desarrollo web", "Construcción y mantenimiento de sitios y aplicaciones web mediante tecnologías y código.", "Convertir el diseño del panel en HTML, CSS y comportamiento con JavaScript.", null, []], ["Etiqueta HTML", "HTML tag", "Etiqueta HTML", "Marca escrita entre signos < y > que delimita un elemento. Muchas tienen apertura y cierre; los elementos vacíos, como img, no tienen etiqueta de cierre.", "<p> abre un párrafo y </p> lo cierra.", "<p>Hola</p>", []], ["Elemento HTML", "HTML element", "Elemento HTML", "Unidad del documento: normalmente incluye etiqueta de apertura, contenido y etiqueta de cierre. Hay elementos vacíos.", "Todo <p>Hola</p> representa un elemento de párrafo.", "<p>Hola</p>\n<img src=\"cafe.jpg\" alt=\"Taza de café\">", []], ["Atributo HTML", "HTML attribute", "Atributo HTML", "Información adicional en la etiqueta de apertura que configura o describe el elemento. Algunos atributos son booleanos y no necesitan un valor escrito.", "href indica el destino de un enlace; class asigna clases.", "<a href=\"menu.html\" class=\"enlace\">Menú</a>\n<button disabled>Enviar</button>", []], ["Valor", "Value", "Valor", "Dato asignado a un atributo HTML o a una propiedad CSS. Su significado depende del contexto.", "menu.html es el valor de href; 16px es el valor de gap.", "<a href=\"menu.html\">Menú</a>\n.fila { gap: 16px; }", []], ["Selector CSS", "CSS selector", "Selector CSS", "Patrón que identifica los elementos a los que se aplica una regla de estilo.", "p selecciona párrafos; .tarjeta selecciona una clase; #resumen selecciona un id.", ".tarjeta { color: purple; }", []], ["Propiedad CSS", "CSS property", "Propiedad CSS", "Característica de presentación que se configura dentro de una regla de estilo.", "color es la propiedad y purple es su valor.", ".tarjeta { color: purple; }", []], ["Declaración y regla CSS", "CSS declaration and rule", "Declaración y regla CSS", "Una declaración combina propiedad y valor. Una regla reúne un selector y un bloque de declaraciones.", "color: purple; es una declaración; el ejemplo completo es una regla.", ".tarjeta {\n  color: purple;\n  padding: 16px;\n}", []], ["Lenguaje de programación", "Programming language", "Lenguaje de programación", "Sistema de reglas para expresar instrucciones y algoritmos que un entorno de ejecución puede realizar.", "JavaScript puede evaluar una condición y mostrar un mensaje.", "if (total > 0) {\n  console.log(\"Hay ventas registradas\");\n}", []], ["Frontend", "Front end", "Parte del cliente / interfaz", "Parte de una aplicación web que se presenta y funciona en el navegador. Incluye estructura, estilos e interacciones.", "El menú, las tarjetas y los controles visibles de Café Aurora pertenecen al frontend.", null, []], ["Backend", "Back end", "Parte del servidor", "Parte que procesa solicitudes, aplica reglas y puede acceder a datos en el servidor. Una página estática puede funcionar sin un backend propio.", "Un servidor podría consultar las ventas y enviar los datos al panel.", null, []], ["Navegador", "Web browser", "Navegador web", "Programa que permite acceder a la Web e interpretar documentos HTML, estilos CSS y código JavaScript.", "Chrome, Firefox y Edge son navegadores.", null, []], ["Servidor web", "Web server", "Servidor web", "Software y equipo que reciben solicitudes y entregan recursos web. Puede servir archivos o trabajar con una aplicación de backend.", "Entrega index.html y styles.css cuando visitas el sitio.", null, []], ["Diseño adaptable", "Responsive web design", "Diseño web adaptable", "Enfoque que adapta la distribución y el contenido al espacio disponible en distintos dispositivos.", "Las tarjetas pueden estar en cuatro columnas en escritorio y en una en móvil.", "@media (max-width: 600px) {\n  .kpi-grid { grid-template-columns: 1fr; }\n}", []], ["Clase e identificador", "Class and identifier", "Clase e identificador", "class permite agrupar elementos para compartir estilos o comportamiento; id identifica un elemento y debe ser único dentro del documento.", "Varias tarjetas pueden tener class=\"tarjeta\", pero solo un elemento debe tener id=\"resumen\".", "<section id=\"resumen\">\n  <article class=\"tarjeta\">Ventas</article>\n  <article class=\"tarjeta\">Reservas</article>\n</section>", []], ["Biblioteca", "Library", "Biblioteca", "Conjunto de recursos reutilizables para facilitar tareas. Puede contener código, componentes o iconos.", "Bootstrap Icons proporciona iconos reutilizables; no requiere usar todo Bootstrap.", null, []]];
const resources=[["Bootstrap Icons", "Iconos para tu página", "Busca un icono y consulta su nombre, su código SVG o su clase. Es una biblioteca de iconos que puedes usar sin el framework Bootstrap.", "https://icons.getbootstrap.com/", "Abrir Bootstrap Icons"], ["Figma", "Diseño y prototipos", "Planifica la distribución de tu página y prepara un prototipo antes de construirla con código.", "https://www.figma.com/", "Abrir Figma"], ["MDN · HTML", "Referencia de etiquetas", "Consulta la estructura, los elementos y los atributos de HTML.", "https://developer.mozilla.org/es/docs/Web/HTML", "Consultar HTML"], ["MDN · CSS", "Referencia de estilos", "Consulta propiedades, valores, selectores y ejemplos de CSS.", "https://developer.mozilla.org/es/docs/Web/CSS", "Consultar CSS"], ["MDN · JavaScript", "Referencia de programación", "Consulta los fundamentos y ejemplos del lenguaje JavaScript.", "https://developer.mozilla.org/es/docs/Web/JavaScript", "Consultar JavaScript"]];
function show(view){if("speechSynthesis" in window)window.speechSynthesis.cancel();document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});const titles={resources:['Insumos para tu clase.','Herramientas y referencias para diseñar y construir páginas web.'],concepts:['El vocabulario de la Web.','Conceptos, términos en inglés y ejemplos para empezar.'],weeks:['Tu clase, semana a semana.','Ruta propuesta a partir del proyecto Café Aurora trabajado en clase.'],html:['Cada etiqueta tiene una intención.','Consulta su significado, su sintaxis y cuándo utilizarla.'],css:['De la propiedad al resultado.','Propiedades y valores que aparecen en styles.css de Café Aurora.'],compare:['Se parecen. ¿Hacen lo mismo?','Compara su significado y su comportamiento con ejemplos visibles.']};$('#page-title').textContent=titles[view][0];$('#page-desc').textContent=titles[view][1];
if(view==='weeks')$('#view').innerHTML='<div class="grid">'+weeks.map(w=>'<article class="card week"><div class="week-head"><span class="week-number">SEMANA '+w[0]+'</span><span class="topic">'+w[2]+'</span></div><h2>'+w[1]+'</h2><p>'+w[3]+'</p><div class="tags">'+w[4].map(t=>'<code>'+escapeHTML(t)+'</code>').join('')+'</div><button class="text-button" data-go="'+w[6]+'">Consultar '+(w[6]==='compare'?'la comparación':w[2])+'</button><p class="practice"><strong>Práctica:</strong> '+w[5]+'</p></article>').join('')+'</div>';
if(view==='html')$('#view').innerHTML='<div class="notice"><p><strong>HTML describe el contenido.</strong> Estas fichas recogen las etiquetas de Café Aurora. Los ejemplos marcados como mejora incorporan ajustes de semántica o accesibilidad. CSS puede cambiar su apariencia, pero no cambia el significado de una etiqueta.</p></div><div class="grid">'+html.map(h=>'<article class="card"><h2><code>&lt;'+escapeHTML(h[0])+'&gt;</code></h2><p>'+h[1]+'</p>'+code(h[2])+(h[3]?'<div class="label">RESULTADO</div><div class="preview">'+h[3]+'</div>':'')+'</article>').join('')+'</div>';
if(view==='css')$('#view').innerHTML='<div class="notice"><p><code>.tarjeta { color: #7030a0; }</code><br><span class="micro"><strong>.tarjeta</strong> es el selector · <strong>color</strong> es la propiedad · <strong>#7030a0</strong> es el valor.</span></p></div><div class="grid">'+css.map(c=>'<article class="card"><h2><code>'+c[0]+'</code></h2><p>'+c[1]+'</p>'+code(c[2])+'</article>').join('')+'</div>';
if(view==='compare')$('#view').innerHTML=`<article class="card compare-section"><span class="label">01 · SIGNIFICADO Y PRESENTACIÓN</span><h2 style="margin-top:10px"><code>p</code>, <code>span</code> y <code>strong</code></h2><div class="table-wrap"><table><thead><tr><th>Etiqueta</th><th>Qué significa</th><th>Presentación por defecto</th><th>Cuándo usarla</th></tr></thead><tbody><tr><td><code>&lt;p&gt;</code></td><td>Un párrafo.</td><td>Bloque.</td><td>Una idea expresada en un párrafo.</td></tr><tr><td><code>&lt;span&gt;</code></td><td>Agrupación sin significado propio.</td><td>En línea.</td><td>Aplicar una clase a parte del texto.</td></tr><tr><td><code>&lt;strong&gt;</code></td><td>Gran importancia, seriedad o urgencia.</td><td>En línea; generalmente en negrita.</td><td>Marcar un aviso importante.</td></tr></tbody></table></div>${code('<p>Hoy estudio <span class="tema">HTML</span>.\n<strong>Guarda el archivo antes de cerrar.</strong></p>')}<div class="preview"><p>Hoy estudio <span style="color:#7030a0">HTML</span>. <strong>Guarda el archivo antes de cerrar.</strong></p></div><p class="micro">Pueden combinarse: span y strong pueden estar dentro de un párrafo. Para una negrita puramente visual, usa font-weight.</p></article>
<article class="card compare-section"><span class="label">02 · SEPARAR Y DISTRIBUIR</span><h2 style="margin-top:10px"><code>space-between</code> y <code>gap</code></h2><p><strong>gap es una propiedad.</strong> Define una separación. <strong>space-between es un valor de justify-content.</strong> Distribuye el espacio libre entre los elementos; en este ejemplo el primero y el último quedan en los extremos del área de contenido.</p><div class="controls"><label for="demo-width">Ancho del ejemplo</label><input type="range" min="65" max="100" value="100" id="demo-width"><output id="width-out" for="demo-width">100%</output></div><div class="demo-stack"><div class="demo-label">justify-content: space-between;</div><div class="demo-row between">${boxes()}</div><div class="demo-label">gap: 16px;</div><div class="demo-row gap">${boxes()}</div><div class="demo-label">gap: 16px; + space-between;</div><div class="demo-row between gap">${boxes()}</div></div><div class="grid" style="margin-top:16px"><div>${code('.fila {\n  display: flex;\n  justify-content: space-between;\n}')}</div><div>${code('.fila {\n  display: flex;\n  gap: 16px;\n}')}</div></div><p class="micro">En estas filas, las cajas no crecen ni se encogen. Con gap solo, la separación permanece en 16px. Con space-between cambia al variar el ancho si hay espacio libre. Pueden combinarse: la distribución añade espacio al gap. Ninguno añade por sí mismo relleno exterior al contenedor.</p><a class="micro" href="https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/gap" target="_blank" rel="noopener">Referencia: gap</a> · <a class="micro" href="https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/justify-content" target="_blank" rel="noopener">Referencia: justify-content</a></article>
<div class="grid"><article class="card"><span class="label">03 · MODELO DE CAJA</span><h2 style="margin-top:10px">Margin y padding</h2><p><strong>margin:</strong> espacio por fuera del borde. <strong>padding:</strong> espacio entre el contenido y el borde.</p><div class="box-model"><span class="micro">Espacio exterior (margin)</span><div class="box-border"><span class="micro">Espacio interior (padding)</span><div class="box-content">Contenido</div></div></div>${code('.tarjeta {\n  margin: 24px;\n  padding: 16px;\n  border: 2px solid #7030a0;\n}')}<p class="micro">El esquema representa las zonas. Los márgenes verticales de bloques pueden colapsar; el padding no.</p></article>
<article class="card"><span class="label">04 · COLUMNAS</span><h2 style="margin-top:10px">1fr y 2fr</h2><p><code>repeat(4, 1fr)</code> reparte en cuatro partes iguales el espacio disponible para las columnas.</p><div class="grid-example"><span>1fr</span><span>1fr</span><span>1fr</span><span>1fr</span></div>${code('grid-template-columns: repeat(4, 1fr);')}<p><code>2fr 1fr 1fr</code> reparte ese espacio en proporción 2:1:1.</p><div class="grid-example" style="grid-template-columns:2fr 1fr 1fr"><span>2fr</span><span>1fr</span><span>1fr</span></div><p class="micro">fr no equivale directamente a un porcentaje: se reparte el espacio restante tras considerar gaps y otras pistas. El mínimo del contenido puede limitar el reparto.</p></article>
<article class="card"><span class="label">05 · ESTRUCTURA</span><h2 style="margin-top:10px">Div, section y article</h2><p><strong>div:</strong> agrupa sin significado propio.<br><strong>section:</strong> agrupa un tema, normalmente con encabezado.<br><strong>article:</strong> contenido que tiene sentido por sí solo.</p><p class="micro">La forma de tarjeta no determina la etiqueta. El significado del contenido sí.</p></article>
<article class="card"><span class="label">06 · BORDES</span><h2 style="margin-top:10px">¿Por qué no se ve el borde?</h2><p>Definir border-width y border-color no basta si border-style sigue en none.</p>${code('/* Define también el estilo */\nborder-width: 2px;\nborder-color: #7030a0;\nborder-style: solid;\n\n/* Abreviatura equivalente */\nborder: 2px solid #7030a0;')}</article></div>`;
if(view==='compare')$('#view').innerHTML+=`<article class="card compare-section" style="margin-top:22px"><span class="label">07 · EN EL ARCHIVO DE CLASE</span><h2 style="margin-top:10px">La cuadrícula de Café Aurora</h2>${code('.kpi-grid {\n  display: grid;\n  grid-template-columns: 1fr 3fr 1fr;\n}')}<div class="grid-example" style="grid-template-columns:1fr 3fr 1fr"><span>1fr</span><span>3fr</span><span>1fr</span></div><p>Define tres columnas en proporción 1:3:1. El HTML compartido tiene un solo article: las otras dos columnas quedan sin tarjetas. Para cuatro columnas iguales, usa repeat(4, 1fr) y agrega cuatro tarjetas.</p></article><article class="card compare-section"><span class="label">08 · APRENDER REVISANDO</span><h2 style="margin-top:10px">Ajustes útiles del ejemplo</h2><div class="table-wrap"><table><thead><tr><th>En el archivo</th><th>Versión recomendada</th><th>Por qué</th></tr></thead><tbody><tr><td><code>lang="en"</code></td><td><code>lang="es"</code></td><td>El contenido está en español.</td></tr><tr><td>Un p dentro de span.trend</td><td>Texto directamente dentro del span.</td><td>span admite contenido de frase; p no pertenece a esa categoría.</td></tr><tr><td>Un p dentro de button</td><td>Texto o un span.</td><td>El botón admite contenido de frase, no un párrafo.</td></tr><tr><td>Select con id y name vacíos</td><td>Id, name y label asociados.</td><td>Permite identificar el control y darle un nombre accesible.</td></tr><tr><td>Todas las opciones con value=""</td><td>mes, trimestre y anio.</td><td>Distingue los valores de la selección.</td></tr><tr><td>Botón con solo un icono</td><td><code>aria-label="Menú de usuario"</code></td><td>Da un nombre accesible a la acción.</td></tr></tbody></table></div><p class="micro">Bootstrap Icons aporta iconos; no es la hoja de estilos de todo Bootstrap. El botón Exportar del ejemplo aún no tiene una función de exportación.</p><a href="https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/button" target="_blank" rel="noopener">Referencia: contenido de button</a></article><article class="card"><h2>Etiqueta, atributo, selector y valor</h2>${code('<h2 id="summary_title" class="titulo">Resumen</h2>\n\n#summary_title { margin: 0; }\n.titulo { font-weight: bold; }')}<p><strong>h2:</strong> etiqueta. <strong>id y class:</strong> atributos. <strong>#summary_title y .titulo:</strong> selectores. <strong>font-weight:</strong> propiedad. <strong>bold:</strong> valor.</p><p>Un id identifica un elemento y debe ser único en el documento. Una clase se puede compartir entre varios elementos.</p><p><code>.icono_taza h1</code> es un selector descendiente: selecciona los h1 que estén dentro de un elemento con clase icono_taza.</p>${code('/* @import es una regla, no una propiedad */\n@import url("https://fonts.googleapis.com/css2?family=Inter&display=swap");')}<p class="micro">En styles.css, @import carga la fuente Inter. Las reglas y pseudoclases se estudian por separado de las propiedades.</p></article>`;

if(view==='resources')$('#view').innerHTML='<div class="grid">'+resources.map(r=>'<article class="card"><span class="label">'+r[1]+'</span><h2 style="margin-top:10px">'+r[0]+'</h2><p>'+r[2]+'</p><a class="resource-link" href="'+r[3]+'" target="_blank" rel="noopener noreferrer">'+r[4]+'</a></article>').join('')+'</div>';
if(view==='concepts'){
$('#view').innerHTML='<div class="notice"><p>HTML estructura el contenido · CSS define su presentación · JavaScript añade lógica e interacción.</p></div><div class="audio-toolbar"><p class="micro">Pulsa el altavoz para escuchar el término en inglés. La voz depende del navegador y del dispositivo.</p><button class="stop-audio" type="button">Detener audio</button></div><p id="audio-status" class="micro" role="status" aria-live="polite"></p><div class="grid">'+concepts.map((c,i)=>'<article class="card concept"><div class="concept-heading"><h2>'+c[0]+'</h2><button class="speak" type="button" data-speak="'+i+'" aria-label="Escuchar '+c[1]+' en inglés" title="Escuchar en inglés"><svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4zM15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14"/></svg></button></div><p class="english" lang="en">'+c[1]+'</p><p class="translation">'+c[2]+'</p><p>'+escapeHTML(c[3])+'</p>'+(c[6].length?'<dl class="word-meanings">'+c[6].map(w=>'<dt lang="en">'+w[0]+'</dt><dd>'+w[1]+'</dd>').join('')+'</dl>':'')+'<p class="practice"><strong>Ejemplo:</strong> '+escapeHTML(c[4])+'</p>'+(c[5]?code(c[5]):'')+'</article>').join('')+'</div><p class="micro">Referencia: <a href="https://developer.mozilla.org/en-US/docs/Glossary" target="_blank" rel="noopener">Glosario de MDN</a>.</p>';
const supported='speechSynthesis' in window && 'SpeechSynthesisUtterance' in window;
if(!supported){$('#audio-status').textContent='Este navegador no admite lectura en voz alta. Puedes consultar los términos escritos.';document.querySelectorAll('.speak,.stop-audio').forEach(b=>b.disabled=true);}
document.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',()=>{
window.speechSynthesis.cancel();const text=concepts[Number(b.dataset.speak)][1];const utterance=new SpeechSynthesisUtterance(text);utterance.lang='en-US';utterance.rate=0.85;const voice=window.speechSynthesis.getVoices().find(v=>v.lang==='en-US')||window.speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith('en'));if(voice)utterance.voice=voice;
const status=$('#audio-status');utterance.onstart=()=>{status.textContent='Reproduciendo: '+text;};utterance.onend=()=>{status.textContent='Lectura finalizada: '+text;};utterance.onerror=e=>{if(e.error!=='interrupted'&&e.error!=='canceled')status.textContent='No se pudo reproducir el audio. Comprueba que tu dispositivo tenga una voz en inglés disponible.';};window.speechSynthesis.speak(utterance);
}));$('.stop-audio').addEventListener('click',()=>{window.speechSynthesis.cancel();$('#audio-status').textContent='Audio detenido.';});
}
document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>{show(b.dataset.go);window.scrollTo({top:0,behavior:'smooth'})}));if(view==='compare')$('#demo-width').addEventListener('input',e=>{$('.demo-stack').style.width=e.target.value+'%';$('#width-out').textContent=e.target.value+'%'});
}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{show(b.dataset.view);window.scrollTo({top:0,behavior:'smooth'})}));show('weeks');
